function citationText(r,style='mla',page=''){
 const title=r.title||'',year=r.year||'',author=citationAuthor(r),pub=r.publisher||'',container=r.container||'',url=r.url||'';
 let lead=author?author+(r.role==='编'?(style==='mla'?', editor. ':', ed. '):'. '):'';
 if(r.kind==='doctorate')return lead+'“'+title+'.” '+(style==='mla'?[r.institution,year,'PhD dissertation'].filter(Boolean).join(', '):['PhD diss.',r.institution,year].filter(Boolean).join(', '))+'.'+(url?' '+url+'.':'');
 if(['article','interview','web','translation-excerpt'].includes(r.kind)){
  let s=lead+'“'+title+'.” '+[container,r.translator?'Translated by '+r.translator:'',year,r.pages?'pp. '+r.pages:''].filter(Boolean).join(', ')+'.';
  if(url)s+=' '+url+'.'; if(r.kind==='web'&&!year)s+=' '+(style==='mla'?'Accessed 4 Nov. 2026.':'Accessed November 4, 2026.');return s.replace(/\.\./g,'.');
 }
 const trans=r.translator?'Translated by '+r.translator+(style==='mla'?', ':'. '):'';
 return lead+title+'. '+trans+[r.edition,pub,year].filter(Boolean).join(', ')+'.'+(page&&style==='chicago'?' '+page+'.':'');
}
async function copyCitation(text,button){try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(text);else{const area=document.createElement('textarea');area.value=text;document.body.append(area);area.select();if(!document.execCommand('copy'))throw Error('copy');area.remove()}button.textContent=libraryLabels()[9]}catch{const area=document.createElement('textarea');area.value=text;area.setAttribute('aria-label',libraryLabels()[8]);button.after(area);area.select()}}
function editionCitationRecord(e){return {id:e.id,title:e.title,author:e.author||'',role:e.role||'',publisher:e.publisher,year:(e.printingDate||e.editionDate)?.slice(0,4)||'',kind:'book',category:2,edition:[e.volume,e.printingDate&&e.editionDate&&e.printingDate.slice(0,4)!==e.editionDate.slice(0,4)?e.printingDate.slice(0,4)+'年印本':''].filter(Boolean).join(' · '),incomplete:!(e.printingDate||e.editionDate)||!e.publisher||!e.author}}
const citationRecords=[];
for(const w of works){if(w.group==='出版'&&editionsFor(w.title).length)continue;citationRecords.push({id:'w-'+w.id,title:w.title,author:w.group==='翻译'?(w.originalAuthor||''):'王安忆',translator:w.group==='翻译'?'王安忆':'',publisher:w.publisher||'',year:w.date?.match(/\d{4}/)?.[0]||'',container:w.issue||'',kind:w.group==='发表'?'article':'book',category:2,url:w.source||'',href:'#works/'+w.id,incomplete:!w.date||((w.group!=='发表')&&!w.publisher)})}
for(const e of suppliedEditions.filter(e=>e.kind!=='研究资料汇编')){const r=editionCitationRecord(e);const w=works.find(w=>w.group==='出版'&&w.title===e.title);r.href=w?'#works/'+w.id:'#home';citationRecords.push(r)}
for(const r of researchLibrary){citationRecords.push({id:'research-'+r.id,title:r.title,author:r.author,role:r.role,publisher:r.publisher,year:r.year?String(r.year):'',institution:r.institution||r.university||'',kind:r.type==='doctoral-dissertation'?'doctorate':r.type==='dissertation'?'doctorate':r.type==='doctoral'?'doctorate':r.type==='book'?'book':'doctorate',category:r.type==='book'?3:4,url:r.url||r.source,href:'#research',incomplete:!r.year})}
for(const r of translationRecords)for(const [i,e]of r.editions.entries())citationRecords.push({id:'tr-'+r.id+'-'+i,title:e.title||r.title||r.original,author:'王安忆',translator:e.translator||r.translator||'',publisher:e.publisher||'',container:e.venue||'',year:e.year||'',pages:e.pages||'',kind:'translation-excerpt',category:5,href:'#translations/'+encodeURIComponent(r.original),incomplete:!(e.title||r.title)||!e.venue});
for(const [i,r]of interviewRecords.entries())citationRecords.push({id:'interview-'+i,title:r.title,author:'王安忆',container:r.source,year:r.date,kind:'interview',category:6,url:r.url,href:'#interviews',incomplete:!r.date});
for(const [i,r]of citationSources.entries())citationRecords.push({id:'source-'+i,title:r.title,author:r.author||'',container:r.organization||'',year:r.date||'',kind:'web',category:7,url:r.url,href:r.url,incomplete:!r.date});
let citationPage=0;
function citationLibraryHTML(){const l=libraryLabels();return '<section class="section citation-library" id="citation-library"><div class="section-head"><h2>'+l[0]+'</h2><span>MLA 9 / Chicago 18</span></div><div class="citation-toolbar"><label>'+l[7]+'<input id="citationSearch" type="search"></label><label>'+l[1]+'<select id="citationCategory">'+[1,2,3,4,5,6,7].map(i=>'<option value="'+i+'">'+l[i]+'</option>').join('')+'</select></label><label>'+l[14]+'<select id="citationStyle"><option value="mla">MLA 9</option><option value="chicago">Chicago 18 · Bibliography</option></select></label></div><p class="source citation-note">'+({zh:'引文使用所列版本。缺项以提示标明，引用前请核对；作品、译本和采访题名保留原语言。',en:'Citations refer to the listed edition. Incomplete records are flagged; titles retain their original language.',fr:'Les références suivent l’édition indiquée. Les notices incomplètes sont signalées ; les titres conservent leur langue originale.'}[document.documentElement.lang.slice(0,2)]||'')+'</p><div class="citation-actions"><span id="citationCount"></span><button id="citationCopyAll">'+l[17]+'</button></div><div id="citationList"></div><div class="citation-pagination"><button id="citationPrev">'+l[15]+'</button><span id="citationPage"></span><button id="citationNext">'+l[16]+'</button></div></section>'}
function citationMarkup(r,style){const text=citationText(r,style),title=esc(r.title);return esc(text).replace(title,(r.kind==='book'?'<i>':'<span>')+title+(r.kind==='book'?'</i>':'</span>'))}
function citationFiltered(){const q=document.querySelector('#citationSearch').value.toLocaleLowerCase().trim(),cat=Number(document.querySelector('#citationCategory').value);return citationRecords.filter(r=>(cat===1||r.category===cat)&&[r.title,r.author,r.year,r.publisher,r.container,r.institution].filter(Boolean).join(' ').toLocaleLowerCase().includes(q))}
function renderCitationLibrary(){const l=libraryLabels(),list=citationFiltered(),style=document.querySelector('#citationStyle').value,size=15;citationPage=Math.min(citationPage,Math.max(0,Math.ceil(list.length/size)-1));document.querySelector('#citationCount').textContent=String(list.length);document.querySelector('#citationList').innerHTML=list.slice(citationPage*size,(citationPage+1)*size).map(r=>'<article class="citation-entry"><div><h3 class="research-original-title">'+esc(r.title)+'</h3><p class="citation-string" lang="'+(/[^\u0000-\u007f]/.test(r.title)?'zh':'en')+'">'+citationMarkup(r,style)+'</p>'+(r.incomplete?'<p class="source">'+l[10]+'</p>':'')+'<a href="'+esc(r.href||'#home')+'">'+l[21]+'</a></div><button data-copy-citation="'+esc(r.id)+'">'+l[8]+'</button></article>').join('')||'<p>'+l[22]+'</p>';document.querySelector('#citationPage').textContent=(citationPage+1)+' / '+Math.max(1,Math.ceil(list.length/size));document.querySelector('#citationPrev').disabled=citationPage===0;document.querySelector('#citationNext').disabled=(citationPage+1)*size>=list.length;document.querySelectorAll('[data-copy-citation]').forEach(b=>b.onclick=()=>copyCitation(citationText(citationRecords.find(r=>r.id===b.dataset.copyCitation),style),b))}
function bindCitationLibrary(){if(!document.querySelector('#citationSearch'))return;for(const id of ['citationSearch','citationCategory','citationStyle'])document.getElementById(id).addEventListener(id==='citationSearch'?'input':'change',()=>{citationPage=0;renderCitationLibrary()});document.querySelector('#citationPrev').onclick=()=>{citationPage--;renderCitationLibrary()};document.querySelector('#citationNext').onclick=()=>{citationPage++;renderCitationLibrary()};document.querySelector('#citationCopyAll').onclick=e=>copyCitation(citationFiltered().map(r=>citationText(r,document.querySelector('#citationStyle').value)).join('\n\n'),e.currentTarget);renderCitationLibrary()}
const homeBeforeLibrary=home;home=function(){return homeBeforeLibrary()+citationLibraryHTML()};
const openWorkBeforeCitations=openWork;
openWork=function(id){openWorkBeforeCitations(id);const w=works.find(w=>w.id===id),editions=w.group==='出版'?editionsFor(w.title):[],l=libraryLabels(),body=document.querySelector('#detailBody');if(!editions.length)return;const section=Array.from(body.querySelectorAll('section')).find(s=>s.querySelector('.publication-history'));if(section){const rows=Array.from(section.querySelectorAll('tbody tr'));const periodicalLabel=workRecordLabels().periodical;for(const row of rows)if(row.querySelector('td')?.textContent!==periodicalLabel)row.remove();section.querySelector('.record-differences')?.remove();if(!section.querySelector('tbody tr'))section.remove();}const box=document.createElement('section');box.className='record-section edition-citations';box.innerHTML='<h3>'+l[11]+'</h3><label>'+l[11]+'<select id="editionChoice">'+editions.map((e,i)=>'<option value="'+i+'">'+esc([e.title,e.volume,e.publisher,e.editionDate,e.isbn?'ISBN '+e.isbn:''].filter(Boolean).join(' · '))+'</option>').join('')+'</select></label><div id="editionFacts"></div><div class="citation-toolbar"><label>'+l[14]+'<select id="workCitationStyle"><option value="mla">MLA 9</option><option value="chicago">Chicago 18</option></select></label><label>'+l[18]+'<input id="workCitationPage" inputmode="numeric"></label></div><p class="citation-string" id="workCitationText"></p><p id="workCitationExample" class="citation-string"></p><button id="workCopyCitation">'+l[8]+'</button>';body.querySelector('.work-synopsis').after(box);
 function update(){const e=editions[Number(document.querySelector('#editionChoice').value)],style=document.querySelector('#workCitationStyle').value,page=document.querySelector('#workCitationPage').value.trim(),r=editionCitationRecord(e);const currentCover=suppliedCovers.find(c=>c.bookId===e.id);if(currentCover){const img=body.querySelector('.work-cover img');if(img)img.src=currentCover.asset;const caption=body.querySelector('.work-cover figcaption');if(caption)caption.textContent=[e.publisher,e.printingDate||e.editionDate,l[11]].filter(Boolean).join(' · ');}document.querySelector('#editionFacts').innerHTML='<p>'+esc(e.publisher||'')+(e.isbn?' · ISBN '+esc(e.isbn):'')+'</p><p>'+l[12]+': '+esc(e.editionDate||l[20])+(e.printingDate?' · '+l[13]+': '+esc(e.printingDate):'')+'</p>';const text=citationText(r,style);document.querySelector('#workCitationText').innerHTML=citationMarkup(r,style);const example=page?(style==='mla'?'('+e.author+', '+e.title+' '+page+')':e.author+', '+e.title+' ('+[e.publisher,(e.printingDate||e.editionDate)?.slice(0,4)].filter(Boolean).join(', ')+'), '+page+'.'):'';document.querySelector('#workCitationExample').textContent=example;document.querySelector('#workCopyCitation').onclick=ev=>copyCitation(text+(example?'\n'+example:''),ev.currentTarget)}
 for(const id of ['editionChoice','workCitationStyle','workCitationPage'])document.getElementById(id).addEventListener(id==='workCitationPage'?'input':'change',update);update();
};
const renderBeforeCitationLibrary=render;render=function(){renderBeforeCitationLibrary();bindCitationLibrary()};
if(!location.hash||location.hash==='#home'||location.hash.startsWith('#works/'))render();

const timelineBeforeSuppliedEditions=publicationTimelineEntries;publicationTimelineEntries=function(){return timelineBeforeSuppliedEditions().map(e=>{const w=works.find(w=>w.id===e.workId);if(w?.dateBeforeSuppliedEdition&&['book','catalogue'].includes(e.kind)){const original=publicationHistoryById.get(w.id)?.book;return {...e,date:original?.date||w.dateBeforeSuppliedEdition,publication:original?.publication||e.publication,source:original?.source||e.source}}return e})};
// Give the homepage directory a stable internal link without changing the main navigation.
const homeBeforeCitationLink=home;home=function(){return homeBeforeCitationLink().replace('<div class="hero-actions">','<div class="hero-actions"><a class="textlink" href="#home/citations">'+libraryLabels()[0]+'</a>')};
const renderBeforeCitationAnchor=render;render=function(){renderBeforeCitationAnchor();if(location.hash==='#home/citations')document.querySelector('#citation-library')?.scrollIntoView({block:'start'})};
for(const e of suppliedEditions){const w=works.find(w=>w.group==='出版'&&w.title===e.title);if(!w||workSummaryRecords.some(s=>s.workId===w.id)||!e.contents?.length)continue;const items=e.contents.filter(t=>typeof t==='string');if(!items.length)continue;workSummaryRecords.push({workId:w.id,heading:'本书简介',summary:'这部'+(e.kind||'作品集')+'收录'+items.slice(0,6).map(t=>'《'+t+'》').join('、')+(items.length>6?'等篇目':'')+'。',source:{title:'项目发起者提供版本·目录',url:'#home'}})}
if(!location.hash||location.hash.startsWith('#home')||location.hash.startsWith('#works/'))render();

const homeBeforeUpdatedCounts=home;home=function(){const count=works.filter(w=>w.group==='出版').length;const description=({zh:'作品目录现收录'+count+'条出版记录、148条期刊发表记录、7条编剧记录与1条翻译记录。每条保留资料来源与核验状态，方便阅读、查证与修订。',en:'The catalogue contains '+count+' book records, 148 journal appearances, 7 screenplay records and 1 translation by Wang Anyi. Bibliographic sources accompany the records.',fr:'Le catalogue réunit '+count+' notices de livres, 148 parutions en revue, 7 travaux scénaristiques et 1 traduction de Wang Anyi. Les sources accompagnent les notices.'})[document.documentElement.lang.slice(0,2)]||'';return homeBeforeUpdatedCounts().replace(/作品目录现收录134条出版记录[^<]+/,description)};
if(!location.hash||location.hash.startsWith('#home'))render();

const researchBooksExpanded=researchLibrary.filter(r=>r.type==='book');researchBooks.splice(0,researchBooks.length,...researchBooksExpanded);
const researchBeforeDoctorates=research;
research=function(){const l=libraryLabels();return researchBeforeDoctorates().replace('</select>','<option value="博士论文">'+l[4]+'</option></select>').replace('围绕王安忆创作的研究著作与资料汇编。',l[3]+' · '+l[4])};
renderResearch=function(){const l=libraryLabels(),q=document.querySelector('#researchSearch').value.trim().toLocaleLowerCase(),type=document.querySelector('#researchCategory').value;const list=researchLibrary.filter(r=>(type==='全部类型'||(r.type==='book'?r.category===type:type==='博士论文'))&&[r.title,r.author,r.publisher,r.university,r.year,r.topic,r.scope,r.language,r.isbn].filter(Boolean).join(' ').toLocaleLowerCase().includes(q));document.querySelector('#researchCount').textContent='显示 '+list.length+' 项研究书目';document.querySelector('#researchList').innerHTML=['专题研究','比较研究','研究资料汇编','博士论文'].map(category=>{const group=list.filter(r=>r.type==='book'?r.category===category:category==='博士论文');if(!group.length)return '';return '<section class="research-shelf"><div class="research-shelf-heading"><h2>'+esc(category==='博士论文'?l[4]:category)+'</h2><span>'+group.length+'</span></div><div class="research-edition-list">'+group.sort((a,b)=>(Number(a.year)||9999)-(Number(b.year)||9999)).map(r=>{const cite=citationRecords.find(c=>c.id==='research-'+r.id),covers=suppliedCovers.filter(c=>(r.suppliedEditions||[]).includes(c.bookId));return '<article class="research-edition"><div class="research-edition-year">'+esc(r.year||r.academicYear||'—')+'</div><div class="research-edition-main">'+covers.map(cover=>'<img class="research-cover" loading="lazy" src="'+esc(cover.asset)+'" alt="'+esc(cover.title)+'">').join('')+'<h3 class="research-original-title">'+esc(r.title)+'</h3><p>'+esc(r.author)+' · '+esc(r.language||'')+'</p><p>'+esc(r.scope||r.topic||'')+'</p><details class="research-edition-detail"><summary>'+l[19]+'</summary><p class="citation-string">'+esc(citationText(cite))+'</p><button data-research-copy="'+esc(r.id)+'">MLA · '+l[8]+'</button><button data-research-chicago="'+esc(r.id)+'">Chicago · '+l[8]+'</button><p>'+esc(r.isbn?'ISBN '+r.isbn:r.degree||'')+'</p></details><p><a target="_blank" rel="noopener" href="'+esc(r.url||r.source)+'">'+l[21]+'</a></p></div><div class="research-edition-publisher">'+esc(r.publisher||r.university||'')+'</div></article>'}).join('')+'</div></section>'}).join('')||l[22];for(const [attr,style]of [['researchCopy','mla'],['researchChicago','chicago']])document.querySelectorAll('[data-'+attr.replace(/[A-Z]/g,m=>'-'+m.toLowerCase())+']').forEach(b=>b.onclick=()=>copyCitation(citationText(citationRecords.find(c=>c.id==='research-'+b.dataset[attr]),style),b))};
if(location.hash.startsWith('#research'))render();
